def _command_complete(self, name, tag):
    logout = (name == 'LOGOUT')
    # BYE is expected after LOGOUT
    if not logout:
        self._check_bye()
    try:
        typ, data = self._get_tagged_response(tag, expect_bye=logout)
    except self.abort as val:
        raise self.abort('command: %s => %s' % (name, val))
    except self.error as val:
        raise self.error('command: %s => %s' % (name, val))
    if not logout:
        self._check_bye()
    if typ == 'BAD':
        raise self.error('%s command error: %s %s' % (name, typ, data))
    return typ, data


def _get_capabilities(self):
    typ, dat = self.capability()
    if dat == [None]:
        raise self.error('no CAPABILITY response from server')
    dat = str(dat[-1], self._encoding)
    dat = dat.upper()
    self.capabilities = tuple(dat.split())


def _get_response(self):

    # Read response and store.
    #
    # Returns None for continuation responses,
    # otherwise first response line received.

    resp = self._get_line()

    # Command completion response?

    if self._match(self.tagre, resp):
        tag = self.mo.group('tag')
        if not tag in self.tagged_commands:
            raise self.abort('unexpected tagged response: %r' % resp)

        typ = self.mo.group('type')
        typ = str(typ, self._encoding)
        dat = self.mo.group('data')
        self.tagged_commands[tag] = (typ, [dat])
    else:
        dat2 = None

        # '*' (untagged) responses?

        if not self._match(Untagged_response, resp):
            if self._match(self.Untagged_status, resp):
                dat2 = self.mo.group('data2')

        if self.mo is None:
            # Only other possibility is '+' (continuation) response...

            if self._match(Continuation, resp):
                self.continuation_response = self.mo.group('data')
                return None     # NB: indicates continuation

            raise self.abort("unexpected response: %r" % resp)

        typ = self.mo.group('type')
        typ = str(typ, self._encoding)
        dat = self.mo.group('data')
        if dat is None: dat = b''        # Null untagged response
        if dat2: dat = dat + b' ' + dat2

        # Is there a literal to come?

        while self._match(self.Literal, dat):

            # Read literal direct from connection.

            size = int(self.mo.group('size'))
            if __debug__:
                if self.debug >= 4:
                    self._mesg('read literal size %s' % size)
            data = self.read(size)

            # Store response with literal as tuple

            self._append_untagged(typ, (dat, data))

            # Read trailer - possibly containing another literal

            dat = self._get_line()

        self._append_untagged(typ, dat)

    # Bracketed response information?

    if typ in ('OK', 'NO', 'BAD') and self._match(Response_code, dat):
        typ = self.mo.group('type')
        typ = str(typ, self._encoding)
        self._append_untagged(typ, self.mo.group('data'))

    if __debug__:
        if self.debug >= 1 and typ in ('NO', 'BAD', 'BYE'):
            self._mesg('%s response: %r' % (typ, dat))

    return resp


def _get_tagged_response(self, tag, expect_bye=False):

    while 1:
        result = self.tagged_commands[tag]
        if result is not None:
            del self.tagged_commands[tag]
            return result

        if expect_bye:
            typ = 'BYE'
            bye = self.untagged_responses.pop(typ, None)
            if bye is not None:
                # Server replies to the "LOGOUT" command with "BYE"
                return (typ, bye)

        # If we've seen a BYE at this point, the socket will be
        # closed, so report the BYE now.
        self._check_bye()

        # Some have reported "unexpected response" exceptions.
        # Note that ignoring them here causes loops.
        # Instead, send me details of the unexpected response and
        # I'll update the code in `_get_response()'.

        try:
            self._get_response()
        except self.abort as val:
            if __debug__:
                if self.debug >= 1:
                    self.print_log()
            raise


def _get_line(self):

    line = self.readline()
    if not line:
        raise self.abort('socket error: EOF')

    # Protocol mandates all lines terminated by CRLF
    if not line.endswith(b'\r\n'):
        raise self.abort('socket error: unterminated line: %r' % line)

    line = line[:-2]
    if __debug__:
        if self.debug >= 4:
            self._mesg('< %r' % line)
        else:
            self._log('< %r' % line)
    return line


def _match(self, cre, s):

    # Run compiled regular expression match method on 's'.
    # Save result, return success.

    self.mo = cre.match(s)
    if __debug__:
        if self.mo is not None and self.debug >= 5:
            self._mesg("\tmatched %r => %r" % (cre.pattern, self.mo.groups()))
    return self.mo is not None


def _new_tag(self):

    tag = self.tagpre + bytes(str(self.tagnum), self._encoding)
    self.tagnum = self.tagnum + 1
    self.tagged_commands[tag] = None
    return tag


def _quote(self, arg):

    arg = arg.replace('\\', '\\\\')
    arg = arg.replace('"', '\\"')

    return '"' + arg + '"'


def _simple_command(self, name, *args):

    return self._command_complete(name, self._command(name, *args))


def _untagged_response(self, typ, dat, name):
    if typ == 'NO':
        return typ, dat
    if not name in self.untagged_responses:
        return typ, [None]
    data = self.untagged_responses.pop(name)
    if __debug__:
        if self.debug >= 5:
            self._mesg('untagged_responses[%s] => %s' % (name, data))
    return typ, data

