    try:
        self.childNodes.remove(oldChild)
    except ValueError:
        raise xml.dom.NotFoundErr()
    oldChild.nextSibling = oldChild.previousSibling = None
    oldChild.parentNode = None
    if self.documentElement is oldChild:
        self.documentElement = None

    return oldChild

