def createTextNode(self, data):
    if not isinstance(data, str):
        raise TypeError("node contents must be a string")
    t = Text()
    t.data = data
    t.ownerDocument = self
    return t

def createCDATASection(self, data):
    if not isinstance(data, str):
        raise TypeError("node contents must be a string")
    c = CDATASection()
    c.data = data
    c.ownerDocument = self
    return c

