                    return _One
                else:
                    return _NegativeOne
            if self_key > other_key:
                if sign:
                    return _NegativeOne
                else:
                    return _One
            return _Zero

        if sign:
            if self_nan == 1:
                return _NegativeOne
            if other_nan == 1:
                return _One
            if self_nan == 2:
                return _NegativeOne
            if other_nan == 2:
                return _One
        else:
            if self_nan == 1:
                return _One
            if other_nan == 1:
                return _NegativeOne
            if self_nan == 2:
                return _One
            if other_nan == 2:
                return _NegativeOne

    if self < other:
        return _NegativeOne
    if self > other:
        return _One

    if self._exp < other._exp:
        if sign:
            return _One
        else:
            return _NegativeOne
    if self._exp > other._exp:
        if sign:
            return _NegativeOne
        else:
            return _One
    return _Zero

