def save_tuple(self, obj):
    if not obj: # tuple is empty
        if self.bin:
            self.write(EMPTY_TUPLE)
        else:
            self.write(MARK + TUPLE)
        return

    n = len(obj)
    save = self.save
    memo = self.memo
    if n <= 3 and self.proto >= 2:
        for element in obj:
            save(element)
