def preprocess(self, source, output_file=None, macros=None,
               include_dirs=None, extra_preargs=None, extra_postargs=None):
    fixed_args = self._fix_compile_args(None, macros, include_dirs)
    ignore, macros, include_dirs = fixed_args
    pp_opts = gen_preprocess_options(macros, include_dirs)
    pp_args = self.preprocessor + pp_opts
    if output_file:
        pp_args.extend(['-o', output_file])
    if extra_preargs:
        pp_args[:0] = extra_preargs
    if extra_postargs:
        pp_args.extend(extra_postargs)
    pp_args.append(source)

    # We need to preprocess: either we're being forced to, or we're
    # generating output to stdout, or there's a target output file and
    # the source file is newer than the target (or the target doesn't
    # exist).
    if self.force or output_file is None or newer(source, output_file):
        if output_file:
            self.mkpath(os.path.dirname(output_file))
        try:
            self.spawn(pp_args)
        except DistutilsExecError as msg:
            raise CompileError(msg)

def _compile(self, obj, src, ext, cc_args, extra_postargs, pp_opts):
    compiler_so = self.compiler_so
    if sys.platform == 'darwin':
        compiler_so = _osx_support.compiler_fixup(compiler_so,
                                                cc_args + extra_postargs)
    try:
        self.spawn(compiler_so + cc_args + [src, '-o', obj] +
                   extra_postargs)
    except DistutilsExecError as msg:
        raise CompileError(msg)

def create_static_lib(self, objects, output_libname,
                      output_dir=None, debug=0, target_lang=None):
    objects, output_dir = self._fix_object_args(objects, output_dir)

    output_filename = \
        self.library_filename(output_libname, output_dir=output_dir)

    if self._need_link(objects, output_filename):
        self.mkpath(os.path.dirname(output_filename))
        self.spawn(self.archiver +
                   [output_filename] +
                   objects + self.objects)

        # Not many Unices required ranlib anymore -- SunOS 4.x is, I
        # think the only major Unix that does.  Maybe we need some
        # platform intelligence here to skip ranlib if it's not
        # needed -- or maybe Python's configure script took care of
        # it for us, hence the check for leading colon.
        if self.ranlib:
            try:
                self.spawn(self.ranlib + [output_filename])
            except DistutilsExecError as msg:
                raise LibError(msg)
    else:
        log.debug("skipping %s (up-to-date)", output_filename)

def link(self, target_desc, objects,
         output_filename, output_dir=None, libraries=None,
         library_dirs=None, runtime_library_dirs=None,
         export_symbols=None, debug=0, extra_preargs=None,
         extra_postargs=None, build_temp=None, target_lang=None):
    objects, output_dir = self._fix_object_args(objects, output_dir)
    fixed_args = self._fix_lib_args(libraries, library_dirs,
                                    runtime_library_dirs)
    libraries, library_dirs, runtime_library_dirs = fixed_args

    # filter out standard library paths, which are not explicitely needed
    # for linking
    system_libdirs = ['/lib', '/lib64', '/usr/lib', '/usr/lib64']
    multiarch = sysconfig.get_config_var("MULTIARCH")
    if multiarch:
        system_libdirs.extend(['/lib/%s' % multiarch, '/usr/lib/%s' % multiarch])
    library_dirs = [dir for dir in library_dirs
                    if not dir in system_libdirs]
    runtime_library_dirs = [dir for dir in runtime_library_dirs
                            if not dir in system_libdirs]

    lib_opts = gen_lib_options(self, library_dirs, runtime_library_dirs,
                               libraries)
    if not isinstance(output_dir, (str, type(None))):
        raise TypeError("'output_dir' must be a string or None")
    if output_dir is not None:
        output_filename = os.path.join(output_dir, output_filename)

    if self._need_link(objects, output_filename):
        ld_args = (objects + self.objects +
                   lib_opts + ['-o', output_filename])
        if debug:
            ld_args[:0] = ['-g']
        if extra_preargs:
            ld_args[:0] = extra_preargs
        if extra_postargs:
            ld_args.extend(extra_postargs)
        self.mkpath(os.path.dirname(output_filename))
        try:
            if target_desc == CCompiler.EXECUTABLE:
                linker = self.linker_exe[:]
            else:
                linker = self.linker_so[:]
            if target_lang == "c++" and self.compiler_cxx:
                # skip over environment variable settings if /usr/bin/env
                # is used to set up the linker's environment.
                # This is needed on OSX. Note: this assumes that the
                # normal and C++ compiler have the same environment
                # settings.
                i = 0
                if os.path.basename(linker[0]) == "env":
                    i = 1
                    while '=' in linker[i]:
                        i += 1

                if os.path.basename(linker[i]) == 'ld_so_aix':
                    # AIX platforms prefix the compiler with the ld_so_aix
                    # script, so we need to adjust our linker index
                    offset = 1
                else:
                    offset = 0

                linker[i+offset] = self.compiler_cxx[i]

            if sys.platform == 'darwin':
                linker = _osx_support.compiler_fixup(linker, ld_args)

            self.spawn(linker + ld_args)
        except DistutilsExecError as msg:
            raise LinkError(msg)
    else:
        log.debug("skipping %s (up-to-date)", output_filename)

