    tried.  Instead, just send the ABOR command as OOB data.'''
    line = b'ABOR' + B_CRLF
    if self.debugging > 1:
        print('*put urgent*', self.sanitize(line))
    self.sock.sendall(line, MSG_OOB)
    resp = self.getmultiline()
    if resp[:3] not in {'426', '225', '226'}:
