            if resp[0] != '1':
                raise error_reply(resp)
        except:
            conn.close()
            raise
    else:
        with self.makeport() as sock:
            if rest is not None:
                self.sendcmd("REST %s" % rest)
            resp = self.sendcmd(cmd)
            # See above.
            if resp[0] == '2':
                resp = self.getresp()
            if resp[0] != '1':
                raise error_reply(resp)
