def _start_handshake(self):
    if self._loop.get_debug():
        logger.debug("%r starts SSL handshake", self)
        self._handshake_start_time = self._loop.time()
    else:
        self._handshake_start_time = None

    self._set_state(SSLProtocolState.DO_HANDSHAKE)

    # start handshake timeout count down
    self._handshake_timeout_handle = \
        self._loop.call_later(self._ssl_handshake_timeout,
                              lambda: self._check_handshake_timeout())

    self._do_handshake()

def _check_handshake_timeout(self):
    if self._state == SSLProtocolState.DO_HANDSHAKE:
        msg = (
            f"SSL handshake is taking longer than "
            f"{self._ssl_handshake_timeout} seconds: "
            f"aborting the connection"
        )
        self._fatal_error(ConnectionAbortedError(msg))

def _do_handshake(self):
    try:
        self._sslobj.do_handshake()
    except SSLAgainErrors:
        self._process_outgoing()
    except ssl.SSLError as exc:
        self._on_handshake_complete(exc)
    else:
        self._on_handshake_complete(None)

def _on_handshake_complete(self, handshake_exc):
    if self._handshake_timeout_handle is not None:
        self._handshake_timeout_handle.cancel()
        self._handshake_timeout_handle = None

    sslobj = self._sslobj
    try:
        if handshake_exc is None:
            self._set_state(SSLProtocolState.WRAPPED)
        else:
            raise handshake_exc

        peercert = sslobj.getpeercert()
    except Exception as exc:
        self._set_state(SSLProtocolState.UNWRAPPED)
        if isinstance(exc, ssl.CertificateError):
            msg = 'SSL handshake failed on verifying the certificate'
        else:
            msg = 'SSL handshake failed'
        self._fatal_error(exc, msg)
        self._wakeup_waiter(exc)
        return

    if self._loop.get_debug():
        dt = self._loop.time() - self._handshake_start_time
        logger.debug("%r: SSL handshake took %.1f ms", self, dt * 1e3)

    # Add extra info that becomes available after handshake.
    self._extra.update(peercert=peercert,
                       cipher=sslobj.cipher(),
                       compression=sslobj.compression(),
                       ssl_object=sslobj)
    if self._app_state == AppProtocolState.STATE_INIT:
        self._app_state = AppProtocolState.STATE_CON_MADE
        self._app_protocol.connection_made(self._get_app_transport())
    self._wakeup_waiter()
    self._do_read()

# Shutdown flow

def _start_shutdown(self):
    if (
        self._state in (
            SSLProtocolState.FLUSHING,
            SSLProtocolState.SHUTDOWN,
            SSLProtocolState.UNWRAPPED
        )
    ):
        return
    if self._app_transport is not None:
        self._app_transport._closed = True
    if self._state == SSLProtocolState.DO_HANDSHAKE:
        self._abort()
    else:
        self._set_state(SSLProtocolState.FLUSHING)
        self._shutdown_timeout_handle = self._loop.call_later(
            self._ssl_shutdown_timeout,
            lambda: self._check_shutdown_timeout()
        )
        self._do_flush()

def _check_shutdown_timeout(self):
    if (
        self._state in (
            SSLProtocolState.FLUSHING,
            SSLProtocolState.SHUTDOWN
        )
    ):
        self._transport._force_close(
            exceptions.TimeoutError('SSL shutdown timed out'))

def _do_flush(self):
    self._do_read()
    self._set_state(SSLProtocolState.SHUTDOWN)
    self._do_shutdown()

def _do_shutdown(self):
    try:
        if not self._eof_received:
            self._sslobj.unwrap()
    except SSLAgainErrors:
        self._process_outgoing()
    except ssl.SSLError as exc:
        self._on_shutdown_complete(exc)
    else:
        self._process_outgoing()
        self._call_eof_received()
        self._on_shutdown_complete(None)

